Code.NativeIaC:
```bicep
// Enable Table service diagnostic logging
param storageAccountName string
param workspaceId string

resource sa 'Microsoft.Storage/storageAccounts@2023-05-01' existing = {
  name: storageAccountName
}

resource tableSvc 'Microsoft.Storage/storageAccounts/tableServices@2023-05-01' existing = {
  parent: sa
  name: 'default'
}

resource diag 'Microsoft.Insights/diagnosticSettings@2021-05-01-preview' = {
  name: 'diag-table'
  scope: tableSvc
  properties: {
    workspaceId: workspaceId
    logs: [
      { category: 'StorageRead', enabled: true }
      { category: 'StorageWrite', enabled: true }
      { category: 'StorageDelete', enabled: true }
    ]
  }
}
```

Code.Terraform:
```hcl
# Enable Table service diagnostic logging
resource "azurerm_monitor_diagnostic_setting" "example_resource" {
  name                       = "diag-table"
  target_resource_id         = "${azurerm_storage_account.example_resource.id}/tableServices/default"
  log_analytics_workspace_id = azurerm_log_analytics_workspace.example_resource.id

  enabled_log {
    category = "StorageRead"
  }
  enabled_log {
    category = "StorageWrite"
  }
  enabled_log {
    category = "StorageDelete"
  }
}
```
